            deleted=clean('delete-audit-bucket-'+str(attempt),'s3api','delete-bucket',{'Bucket':OWN['bucket']})
            if deleted['code']=='Success':break
            time.sleep(10)
        CAP['cleanup_verification']['bucket']=clean('verify-bucket-absent','s3api','head-bucket',{'Bucket':OWN['bucket']})
    CAP['finished_ms']=int(time.time()*1000);save()

